 , PROJECT_NAME = #{projectName}      
 , DESCRIPTION = #{description}       
 , PROJECT_IMAGE_URL = #{projectImageUrl} 
 , CREATED_AT = #{createdAt}        
 , EMAIL_SEND_TIME = #{emailSendTime}   
 , USER_ID = #{userId}           
WHERE PROJECT_ID = #{projectId}

